Script.script:
ataxia = ataxia or {}
ataxiaTables = ataxiaTables or {}
ataxiaTemp = ataxiaTemp or {}
ataxiaTemp.addedHerbID = 1
ataxiaTemp.removedHerbID = 2
ataxiagui = ataxiagui or {}
ataxiaVersion = "4.3.1"						--last was 4.3
muteList = muteList or {}

ataxiaTables.limbTimers = ataxiaTables.limbTimers or {}
ataxiaTables.fractureTimers = ataxiaTables.fractureTimers or {}

ataxia.bals = ataxia.bals or {}
ataxia.bals.get = {"bal", "eq"}
ataxia.bals.used = ataxia.bals.used or {}
ataxia.bals.timestamps = ataxia.bals.timestamps or {}


function ataxia_Echo(text)
	cecho("\n<a_darkcyan>(<a_darkmagenta>LEVI<a_darkcyan>): <NavajoWhite>"..text)
end

function ataxiaEcho(text)
	cecho("\n<a_darkcyan>(<a_darkmagenta>LEVI<a_darkcyan>): <NavajoWhite>"..text)
end

local minerals = {"antimony", "argentum", "arsenic", "aurum", "azurite", "bisemutum", "calamine", "calcite", "cinnabar", "cuprum", "dolomite", "ferrum", "gypsum", "magnesium", "malachite", "plumbum", "potash", "quartz", "quicksilver", "realgar", "stannum"} local herbs = {"ash", "bayberry", "bellwort", "bloodroot", "cohosh", "elm", "ginger", "ginseng", "goldenseal", "hawthorn", "kelp", "kola", "lobelia", "skullcap", "valerian", "sileris", "irid", "pear"}
ataxiaTemp.keepout = ataxiaTemp.keepout or {}
function populate_keepOut() ataxia.settings.precache = ataxia.settings.precache or {} ataxiaTemp.keepout = {}
for i,v in pairs(ataxia.settings.precache) do ataxiaTemp.keepout[i] = v end end
function ataxia_precacheSet(item, amount) local num = tonumber(amount) if table.contains(minerals, item) or table.contains(herbs, item) then if num > 0 then ataxia.settings.precache[item] = num ataxia_precacheShow() populate_keepOut() ataxia_precacheQueue() ataxia_saveSettings(false) elseif num == 0 then ataxia.settings.precache[item] = nil ataxia_precacheShow() populate_keepOut() ataxia_precacheQueue() ataxia_saveSettings(false) else ataxiaEcho("Number for precache must be 0 or higher.") end else ataxiaEcho("That is not a valid herb or mineral.") end end
function ataxia_precacheShow() ataxiaEcho("System precache settings.") local outriftables = {"antimony", "argentum", "arsenic", "aurum", "azurite", "bisemutum", "calamine", "calcite", "cinnabar", "cuprum", "dolomite", "ferrum", "gypsum", "magnesium", "malachite", "plumbum", "potash", "quartz", "quicksilver", "realgar", "stannum", "ash", "bayberry", "bellwort", "bloodroot", "cohosh", "elm", "ginger", "ginseng", "goldenseal", "hawthorn", "kelp", "kola", "lobelia", "skullcap", "valerian", "sileris", "irid", "pear"} table.sort(outriftables) local x = 0 for n, item in spairs(outriftables) do x = x + 1 local num = 0 if ataxia.settings.precache[item] then num = ataxia.settings.precache[item] end local d = "<a_cyan>[<NavajoWhite>"..num.."<a_cyan>] <DimGrey>" if (x-1)%3 == 0 then echo("\n") end cecho(d) local nWithSpace = item local length = nWithSpace:len() + math.floor(math.log10(math.max(1,num))) if length < 25 and (x-1)%3 ~= 2 then local pad = 25 - length nWithSpace = string.rep(" ", pad) else nWithSpace = "" end cecho("<DimGrey>"..item:title()) echo(" ")
local increase = "pconfig "..item.." "..num + 1 local decrease = "pconfig "..item.." "..num - 1 echoLink("(+)", [[expandAlias("]]..increase..[[")]], "Increase outrift of "..item.." by 1.", true) echo(" ") echoLink("(-)", [[expandAlias("]]..decrease..[[")]], "Decrease outrift of "..item.." by 1.", true) cecho("<DimGrey>"..nWithSpace) end send(" ") end

function outRift_addedItem() if gmcp.Char.Items.Add.location == "inv" then ataxiaTemp.ignoreOutrift = tempTimer(2, [[ataxiaTemp.ignoreOutrift = nil]]) local herbName = returnHerbName(gmcp.Char.Items.Add.item.name)
if herbName then local herbAmount = extractNumberFromString(gmcp.Char.Items.Add.item.name) or 1
ataxiaTemp.outrifted[herbName] = ataxiaTemp.outrifted[herbName] + herbAmount ataxiaTemp.addedHerbID = tonumber(gmcp.Char.Items.Add.item.id)
if ataxiaTemp.outriftTimer then killTimer(ataxiaTemp.outriftTimer) end ataxiaTemp.outriftTimer = tempTimer(2, [[ataxiaTemp.outriftTimer = nil]]) end end end registerAnonymousEventHandler("gmcp.Char.Items.Add", "outRift_addedItem")
function outRift_removedItem() if gmcp.Char.Items.Remove.location == "inv" then ataxiaTemp.ignoreOutrift = tempTimer(2, [[ataxiaTemp.ignoreOutrift = nil]]) local herbName = returnHerbName(gmcp.Char.Items.Remove.item.name)
if herbName then local herbAmount = extractNumberFromString(gmcp.Char.Items.Remove.item.name) or 1 ataxiaTemp.outrifted[herbName] = ataxiaTemp.outrifted[herbName] - herbAmount ataxiaTemp.removedHerbID = tonumber(gmcp.Char.Items.Remove.item.id)
if ataxiaTemp.removedHerbID == ataxiaTemp.addedHerbID then ataxiaTemp.outrifted[herbName] = ataxiaTemp.outrifted[herbName] - 1 ataxiaTemp.addedHerbID = 1 end
if ataxiaTemp.outrifted[herbName] < 0 then ataxiaTemp.outrifted[herbName] = 0 end if not ataxiaTemp.outriftTimer then ataxia_precacheQueue() end end end end
registerAnonymousEventHandler("gmcp.Char.Items.Remove", "outRift_removedItem")

function ataxia_isClass(what) if not gmcp.Char or not gmcp.Char.Status or not gmcp.Char.Status.class then return false end local x = gmcp.Char.Status.class:lower() local y = what:lower()
if y == "knight" and (x == "runewarden" or x == "infernal" or x == "paladin") then return true elseif x == y then return true else return false end end
function getClassArmour() local com = "" local armours = { Alchemist = "ringmail", Apostate = "ringmail", Bard = "leather", Blademaster = "ringmail", Depthswalker = "scalemail", Druid = "chainmail", Infernal = "fullplate", Jester = "scalemail", Monk = "leather", Occultist = "scalemail", Paladin = "fullplate", Priest = "splintmail", Runewarden = "fullplate", Sentinel = "chainmail", Serpent = "scalemail", Shaman = "scalemail", Sylvan = "chainmail", Unnamable = "fullplate", } local class = gmcp.Char.Status.class local race = gmcp.Char.Status.race if race ~= "Horkval" then if armours[class] then com = "wear "..armours[class] end end return com end

function ataxia_reportDefences() if not gmcp.Char or not gmcp.Char.Defences or not gmcp.Char.Defences.List then return end if not ataxia.settings or not ataxia.settings.defences then return end local x = "" local cur = ataxia.settings.defences.current local defs = gmcp.Char.Defences.List local defLine, ddx, total = 0, "", 0 local defenceList = { system = {}, other = {}, }
for _, def in pairs(defs) do x = find_defence(def.name) if ataxia.settings.defences.defup[cur][x] then table.insert(defenceList.system, x) else table.insert(defenceList.other, def.name) end end
-- Inject text-tracked defences not reported via GMCP if ataxia.defences["simultaneity"] and ataxia.settings.defences.defup[cur]["simultaneity"] then if not table.contains(defenceList.system, "simultaneity") then table.insert(defenceList.system, "simultaneity") end end
total = #defenceList.other table.sort(defenceList.system)
echo("\n") ataxiaEcho(cur:title().." defences:") echo("\n")
for _, def in pairs(defenceList.system) do defLine = defLine + 1 ddx = "<a_darkcyan>[<green>x<a_darkcyan>] " total = total + 1 if (defLine-1)%3 == 0 then echo("\n") end cecho(ddx)
local dspace = def:title() if dspace:len() < 25 and (defLine-1)%3 ~= 2 then local padding = 25 - dspace:len() dspace = dspace..string.rep(" ", padding) elseif dspace:len() > 25 then dspace:cut(25) end
cecho("<DarkSlateBlue>"..dspace) end
for i,v in pairs(ataxia.settings.defences.defup[cur]) do if not table.contains(defenceList.system, i) then defLine = defLine + 1 ddx = "<a_darkcyan>[<a_red>-<a_darkcyan>] " if (defLine-1)%3 == 0 then echo("\n") end cecho(ddx)
local dspace = i:title() if dspace:len() < 25 and (defLine-1)%3 ~= 2 then local padding = 25 - dspace:len() dspace = dspace..string.rep(" ", padding) elseif dspace:len() > 25 then dspace:cut(25) end cecho("<DarkSlateBlue>"..dspace) end end
echo("\n") ataxiaEcho("Other defences:") echo("\n") defLine = 0
for _,v in pairs(defenceList.other) do defLine = defLine + 1 ddx = "<a_darkcyan>[<NavajoWhite>x<a_darkcyan>] "
if (defLine-1)%3 == 0 then echo("\n") end cecho(ddx)
local dspace = v:title() if dspace:len() < 25 and (defLine-1)%3 ~= 2 then local padding = 25 - dspace:len() dspace = dspace..string.rep(" ", padding) elseif dspace:len() > 25 then dspace:cut(25) end
cecho("<DarkSlateBlue>"..dspace) end echo("\n") ataxiaEcho(total.." total defences.") send(" ") end

function getDragonBreath()
	local colour = string.match(gmcp.Char.Status.class, "%w+")
	local types = {
		Black = "acid", Blue = "ice", Golden = "psi", Green = "venom", Red = "dragonfire", Silver = "lightning",
	}
	return types[colour]
end

ataxiaTables.depthswalker = { usedPreempt = false, canPreempt = true, age = 0, wordBal = true, causalityBal = true, }
function ataxia_depthswalkerReset() ataxiaTables = ataxiaTables or {} ataxiaTables.depthswalker = { usedPreempt = false, canPreempt = true, age = 0, wordBal = true, causalityBal = true, }
updating_terminus_abilities = true sendAll("config pagelength 200", "Ab terminus", "config pagelength 60",false) end
function haveWord(word) if ataxiaTables.depthswalker.abilities and ataxiaTables.depthswalker.abilities[word:lower()] then return true else return false end end
function getAgeColour() local num = ataxiaTables.depthswalker.age local col = "DimGrey" if num <= 250 then col = "DimGrey" elseif num <= 400 then col = "yellow" elseif num <= 600 then col = "orange" else col = "red" end return col end

ScriptGroup.script:
function Geyser.MiniConsole:clear()
	clearWindow(self.name)
end

function Geyser.MiniConsole:append()
	appendBuffer(self.name)
end

Script.script:
function ataxiagui_Create()
	winWid, winHei = getMainWindowSize()
	winHeiP = (winHei/100)
  setConsoleBufferSize("main", 2000000, 2000)

  if ataxia.usegui == true or ataxia.usegui == nil then

    ataxiagui_sep = string.char(getMudletHomeDir():byte()) == "/" and "/" or "\\"		
    ataxiagui_dir = (getMudletHomeDir()..ataxiagui_sep.."Pictures"..ataxiagui_sep):gsub("\\","/")
    ataxiagui_smallUI = false

    if winWid < 1500 then
      ataxiagui_smallUI = true
		  aBorders = {l = 200, t = 30, b = 70, r = 450}
    else
      aBorders = {l = 215, t = 30, b = 70, r = 600}
    end
    setBorderLeft(aBorders.l)
    setBorderTop(aBorders.t)
    setBorderBottom(aBorders.b)
    setBorderRight(aBorders.r)



    ataxiagui_containers()
    ataxiagui_boxes()
    ataxiagui_consoles()
    ataxiagui_createMap()
    ataxiagui_createChat()
    ataxiagui_vitalsElements()
  end
end

function ataxiagui_containers()
	--Initialise containers to hold the various elements of the GUI.
	--The labels beneath each will house the backgrounds.
	ataxiagui.leftContainer = Geyser.Container:new({
		x = 0, y = 0,
		width = aBorders.l, height = winHei,
	})
	ataxiagui.leftBG = Geyser.Label:new({
		x = 0, y = 0,
		width = "100%", height = "100%",
	}, ataxiagui.leftContainer)
	ataxiagui.leftBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[leftBorder.png")]])

	ataxiagui.rightContainer = Geyser.Container:new({
		x = winWid - aBorders.r, y = 0,
		width = aBorders.r, height = winHei,
	})
	ataxiagui.rightBG = Geyser.Label:new({
		x = 0, y = 0,
		width = "100%", height = "100%",
	}, ataxiagui.rightContainer)
	ataxiagui.rightBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[rightBorder.png")]])

	ataxiagui.topContainer = Geyser.Container:new({
		x = aBorders.l, y = 0,
		width = winWid - (aBorders.r + aBorders.l), height = aBorders.t,
	})
	ataxiagui.topBG = Geyser.Label:new({
		x = 0, y = 0,
		width = "100%", height = "100%",
	}, ataxiagui.topContainer)
	ataxiagui.topBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[topBorder.png")]])

	ataxiagui.bottomContainer = Geyser.Container:new({
		x = aBorders.l, y = winHei - aBorders.b,
		width = winWid - (aBorders.r + aBorders.l), height = aBorders.b,
	})
	ataxiagui.bottomBG = Geyser.Label:new({
		x = 0, y = 0,
		width = "100%", height = "100%",
	}, ataxiagui.bottomContainer)
	ataxiagui.bottomBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[bottomBorder.png")]])
end

function ataxiagui_boxes()
	setAppStyleSheet([[
		QScrollBar:vertical {background: #000;}
		QScrollBar::handle:vertical {background-color: #07f; min-height: 50px;}
		QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {background: none; height: 0px;}
		QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {background: none;}
		QMenuBar {background-color: #000; color: #07f;}
		QMenuBar::item:selected {background-color: #000; color: #0ff}
	]])

	ataxiagui.playersBG = Geyser.Label:new({
		x = 0, y = "6%",
		width = "100%", height = "25%",
	}, ataxiagui.leftContainer)
	ataxiagui.playersBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[ataxiaBorder.png")]])

	ataxiagui.roomBG = Geyser.Label:new({
		x = 0, y = "35%",
		width = "100%", height = "25%",
	}, ataxiagui.leftContainer)
	ataxiagui.roomBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[ataxiaBorder.png")]])

	ataxiagui.bashBG = Geyser.Label:new({
		x = 0, y = "65%",
		width = "100%", height = "30%",
	}, ataxiagui.leftContainer)
	ataxiagui.bashBG:setStyleSheet([[border-image: url("]]..ataxiagui_dir..[[ataxiaBorder.png")]])
end

function ataxiagui_consoles()
	ataxiagui.playersConsole = Geyser.MiniConsole:new({
		x = "7%", y = (winHeiP*7)+5,
		width = "86%", height = "22%",
		color = "black",
	}, ataxiagui.leftContainer)

	ataxiagui.roomConsole = Geyser.MiniConsole:new({
		x = "7%", y = (winHeiP*36)+5,
		width = "86%", height = "22%",
		color = "black",
	}, ataxiagui.leftContainer)

	ataxiagui.bashConsole = Geyser.MiniConsole:new({
		x = "7%", y = (winHeiP*66)+5,
		width = "86%", height = "26%",
		color = "black",
	}, ataxiagui.leftContainer)
end

registerAnonymousEventHandler("ataxia system loaded", "ataxiagui_Create")

