		x = 145, y = "7%",
		width = 310, height = "28%",
	}, ataxiagui.rightContainer)

	ataxiagui.mapRoom = Geyser.Label:new({
		x = 110, y = "1%",
		width = 380, height = "3%",
	}, ataxiagui.rightContainer)
