    		padding: 3px;
	]])
	ataxiagui.mapExits:echo([[<p style="font-size:12px"><center><font color="NavajoWhite"><font face="Merienda">]].."Room Exits"..[[</font></p>]] )
-------------------------------------------------------------------------------------------------------------------------------------------------------------------
	ataxiagui.basherBar = Geyser.Gauge:new({
