	ataxiagui.basherBar.front:setStyleSheet([[
		background-color: QLinearGradient(x1: 0, y1: 0, x2: 0, y2: 1, stop: 0 #f1f34e, stop: 0.1 #eef022, stop: 0.49 #a5db67, stop: 0.5 #a5db67, stop: 1 #5e5e19);
		border-top: 2px black solid;
