curingTable = { goldenseal = {"depression", "sandfever", "stupidity", "epilepsy", "dizziness", "dissonance", "shyness", "impatience", "unweavingmind", "fulminated"}, lobelia = {"fratricide", "recklessness", "vertigo", "spiritburn", "tenderskin", "loneliness", "claustrophobia", "masochism", "agoraphobia"}, bellwort = {"timeloop", "justice", "lovers", "peace", "pacified", "generosity", "indifference","diminished"}, kelp = {"hypochondria", "parasite", "weariness", "asthma", "healthleech", "clumsiness", "sensitivity"}, ash = {"confusion", "hypersomnia", "hallucinations", "paranoia", "dementia","crescendo",}, ginseng = {"flushings", "lethargy", "haemophilia", "addiction", "nausea", "scytherus", "darkshade", "unweavingbody"}, }
function haveSmokeAff() local smoke = false local sAffs = {"deadening", "tension", "disloyalty", "hellsight", "manaleech", "slickness", "unweavingspirit","earworm",}
for i=1, #sAffs do if haveAff(sAffs[i]) then smoke = true break end end
return smoke end
function hasSalveAff() local salve = false local sAffs = {"frozen", "shivering", "anorexia", "burns", "ablaze", "selarnia", "damagedleftleg", "damagedrightleg", "mangledleftleg", "mangledrightleg", "damagedleftarm", "damagedrightarm", "mangledleftarm", "mangledrightarm", "brokenleftarm", "brokenrightarm", "brokenleftleg", "brokenrightleg", "hypothermia"}
for i=1, #sAffs do if haveAff(sAffs[i]) then salve = true break end end
return salve end
function restorePassiveCure() cecho("\n<green>+ "..passiveFailsafe.." +") tAffs[passiveFailsafe] = true passiveFailsafe = nil end

Script.script:
function ataxia_nextHarmonic()
if not next(ataxiaTemp.harms) then ataxiaTemp.summoningHarms = nil ataxiaTemp.harmsSummoned = true ataxiaTemp.needSymphony = true ataxiaEcho("Harmonics summoning completed. Refreshing to max duration.") comm = comm.." ;play symphony" else ataxiaEcho("Calling "..ataxiaTemp.harms[1].." next.") comm = "wield rapier;wield lyre;play "..ataxiaTemp.harms[1] end
send("queue addclear free " ..comm) end

