updating_terminus_abilities = true sendAll("config pagelength 200", "Ab terminus", "config pagelength 60",false) end
function haveWord(word) if ataxiaTables.depthswalker.abilities and ataxiaTables.depthswalker.abilities[word:lower()] then return true else return false end end
function getAgeColour() local num = ataxiaTables.depthswalker.age local col = "DimGrey" if num <= 250 then col = "DimGrey" elseif num <= 400 then col = "yellow" elseif num <= 600 then col = "orange" else col = "red" end return col end

Script.script:
lb = lb or {}

function lb.initTarget(name)
  name = name:lower():title()

  lb[name] = lb[name] or {}
  lb[name].t = lb[name].t or {}
  lb[name].hits = lb[name].hits or {
    head = 0,
    torso = 0,
    ["left arm"] = 0,
    ["right arm"] = 0,
    ["left leg"] = 0,
    ["right leg"] = 0,
  }

  raiseEvent("limb hits updated", name, "all")
end

function lb.echo(str)
  cecho("<turquoise>[Limb]: <white>" .. str .. "\n")
end

