if magi.offense.hasAff("shivering") or (tAffs and tAffs.shivering) then tarAffed("shivering") tarAffed("disrupted") tarAffed("frozen") magi.offense.ptRelay(target .. ": Emanation Water (Shivering + Disrupted + Frozen)") elseif not magi.offense.hasAff("frostbite") or (tAffs and tAffs.nocaloric) then tarAffed("shivering") tarAffed("disrupted") magi.offense.ptRelay(target .. ": Emanation Water (Shivering + Disrupted)") else tarAffed("nocaloric") tarAffed("disrupted") magi.offense.ptRelay(target .. ": Emanation Water (Disrupted)") end selectCurrentLine() bg("cyan")

magi.offense = magi.offense or {}
