TriggerGroup.script:
--^\w+ swings .+ at your (.+) with all (?:his|her) might\.$
local weapons = {"Soulpiercer", "Eagle's Scream","rapier"}
for i in pairs(weapons) do if not string.find(multimatches[1][4], weapons[i]) then slc_last_limb = multimatches[1][3] weapcheck = true tempTimer(1, [[weapcheck = false]] )
end end

Trigger.script:
if not monk or not monk.shikudo then return end
monk.shikudo.start()
monk.shikudo.combo_affs = {}
monk.shikudo.parrying = {}

tarAffed("healthleech")
 if partyrelay then send("pt "..target..": healthleech") 
    end

if isTargeted(matches[2]) then
  tarAffed("burning")
  -- Emanation fire applies 2 burn stacks
  magi = magi or {}
  magi.offense = magi.offense or {}
  magi.offense.state = magi.offense.state or {}
  magi.offense.state.burns = math.min((magi.offense.state.burns or 0) + 2, 5)
  tburns = magi.offense.state.burns
end
